27	    fn parse(&self, source: &[char]) -> Vec<Token> {
28	        let mut tokens = Vec::new();
29	        let mut chars_traversed = 0;
30	
31	        for line in source.split(|c| *c == '\n') {
32	            if let Some(trimmed) = trim(line) {
33	                let mut new_tokens = self.inner.parse(trimmed.get_content(line));
34	
35	                new_tokens
36	                    .iter_mut()
37	                    .for_each(|t| t.span.push_by(chars_traversed + trimmed.start));
38	
39	                tokens.append(&mut new_tokens);
40	            }
41	
42	            let line_end = chars_traversed + line.len();
43	
44	            if line_end < source.len() {
45	                tokens.push(Token::new(
46	                    Span::new_with_len(line_end, 1),
47	                    TokenKind::Newline(1),
48	                ));
49	            }
50	
51	            chars_traversed += line.len() + 1;
52	        }
53	
54	        tokens
55	    }
56	}
